async function giSendPaymentAuthOtp(isResend){
  const input=$("paymentAuthIdentifier"),value=String(input?.value||"").trim(),err=$("paymentAuthIdentifierError");
  if(err){err.hidden=true;err.textContent="";}
  if(!giValidLoginIdentifier(value)){
    if(err){err.textContent="Enter a valid mobile number or Email ID.";err.hidden=false;}
    input?.focus();return;
  }
  try{
    const endpoint=isResend?"/auth/otp/resend":"/auth/otp/request";
    const res=await fetch(GIAPIBASE+endpoint,{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({identifier:value})});
    const data=await res.json();
    if(!res.ok)throw new Error(data&&data.message?data.message:"Unable to send OTP.");
    giPaymentAuthApiState.challengeId=data.challengeId?data.challengeId:"";
    giPaymentAuthApiState.identifier=value;
    if($("paymentAuthOtpTarget"))$("paymentAuthOtpTarget").textContent=value;
    if($("paymentAuthIdentifierStep"))$("paymentAuthIdentifierStep").hidden=true;
    if($("paymentAuthOtpStep"))$("paymentAuthOtpStep").hidden=false;
    giPaymentAuthOtpInputs().forEach(i=>i.value="");
    giStartPaymentAuthResend(Number(data.resendAfter)||45);
    requestAnimationFrame(()=>giPaymentAuthOtpInputs()[0]?.focus({preventScroll:true}));
    if(data.debugOtp)console.log("Green Ink DEV payment OTP:",data.debugOtp);
  }catch(ex){
    if(err){err.textContent=ex&&ex.message?ex.message:"Unable to send OTP.";err.hidden=false;}
  }
}
