let giAuthRefreshPromise=null;
async function giRefreshAccessToken(){
  if(giAuthRefreshPromise)return giAuthRefreshPromise;
  giAuthRefreshPromise=(async()=>{
    try{
      const res=await fetch(GIAPIBASE+"/auth/refresh",{method:"POST",credentials:"include"});
      if(!res.ok)return false;
      const data=await res.json();
      giAuthApiState.accessToken=data.accessToken?data.accessToken:"";
      giAuthApiState.expiresIn=Number(data.expiresIn)?Number(data.expiresIn):0;
      giAuthApiState.user=data.user?data.user:giAuthApiState.user;
      return !!giAuthApiState.accessToken;
    }catch(_){return false;}
    finally{giAuthRefreshPromise=null;}
  })();
  return giAuthRefreshPromise;
}
async function giAuthFetch(url,options){
  const opts=Object.assign({},options||{});
  opts.headers=Object.assign({},opts.headers||{});
  if(giAuthApiState.accessToken)opts.headers.Authorization="Bearer "+giAuthApiState.accessToken;
  let res=await fetch(url,opts);
  if(res.status===401&&giAuthApiState.accessToken){
    const refreshed=await giRefreshAccessToken();
    if(refreshed){
      opts.headers.Authorization="Bearer "+giAuthApiState.accessToken;
      res=await fetch(url,opts);
    }
  }
  return res;
}
