function renderNotesTopicList(filter){const q=String(filter||'').trim().toLowerCase(),list=$('notesTopicList');const rows=notesTopicItems.filter(x=>!q||x.title.toLowerCase().includes(q));list.innerHTML=rows.length?rows.map(x=>'<button class="notes-topic-row'+(x.index===notesTopicActive?' active':'')+'" type="button" data-notes-topic-index="'+x.index+'"><span class="notes-topic-row-num">'+(x.index+1)+'.</span><span class="notes-topic-row-title">'+esc(x.title)+'</span><span class="notes-topic-row-arrow">→</span></button>').join(''):'<div class="notes-topic-empty">No matching topic in this chapter.</div>'}
function updateNotesTopicActive(force){if(!notesTopicItems.length)return;const sc=$('notesScroll');if(!sc)return;const y=sc.scrollTop+24;let lo=0,hi=notesTopicPositions.length-1,best=0;while(lo<=hi){const mid=(lo+hi)>>1;if((notesTopicPositions[mid]??0)<=y){best=mid;lo=mid+1}else hi=mid-1}if(force||best!==notesTopicActive){const prev=notesTopicActive;notesTopicActive=Math.max(0,Math.min(notesTopicItems.length-1,best));$('notesTopicCounter').textContent=(notesTopicActive+1)+'/'+notesTopicItems.length;if(notesTopicSheetOpen()){$('notesTopicList').querySelector('[data-notes-topic-index="'+prev+'"]')?.classList.remove('active');$('notesTopicList').querySelector('[data-notes-topic-index="'+notesTopicActive+'"]')?.classList.add('active')}}}
