function enhanceRapidRevisionFinalPoints(root){
  if(!root)return;
  const headings=[...root.querySelectorAll('.gi-revision-topic-heading,.green-ink-history-note-heading')]
    .filter(h=>String(h.textContent||'').includes('Rapid Revision â€” TNPSC Most Expected'));

  headings.forEach(h=>{
    let article=h.nextElementSibling;
    if(!article||article.tagName!=='ARTICLE'){
      const parent=h.parentElement;
      article=parent?.querySelector(':scope > article')||h.nextElementSibling?.querySelector?.('article')||null;
    }
    if(!article)return;

    let items=[...article.querySelectorAll('ul > li')];
    if(!items.length){
      const prose=article.querySelector('.gi-note-prose');
      if(prose)items=[...prose.children].filter(el=>el.tagName==='P');
    }
    if(!items.length)return;

    const last=items[items.length-1];
    if(last.dataset.rapidFinalEnhanced==='1')return;

    const text=String(last.textContent||'').replace(/\s+/g,' ').trim();
    if(!text)return;

    const semicolons=(text.match(/;/g)||[]).length;
    const arrows=(text.match(/→/g)||[]).length;
    const needsEnhancement=text.length>=120||semicolons>=2||arrows>=3;
    if(!needsEnhancement)return;

    last.dataset.rapidFinalEnhanced='1';
    last.classList.add('rapid-final-readable');
    if(last.previousElementSibling){
      last.previousElementSibling.classList.add('rapid-before-final-readable');
    }

    const firstArrow=text.indexOf('→');
    if(firstArrow<1)return;

    const lead=text.slice(0,firstArrow).trim();
    const payload=text.slice(firstArrow+1).trim();
    if(!payload)return;

    last.textContent='';

    const leadEl=document.createElement('div');
    leadEl.className='rapid-final-lead';
    leadEl.textContent=lead;
    last.appendChild(leadEl);

    const parts=payload.split(';').map(x=>x.trim()).filter(Boolean);

    if(parts.length>=2){
      const wrap=document.createElement('div');
      wrap.className='rapid-final-segments';

      parts.forEach(part=>{
        const row=document.createElement('div');
        row.className='rapid-final-segment';

        const dot=document.createElement('span');
        dot.className='rapid-final-dot';
        dot.setAttribute('aria-hidden','true');
        dot.textContent='â€¢';

        const copy=document.createElement('span');
        copy.className='rapid-final-text';
        copy.textContent=part;

        row.append(dot,copy);
        wrap.appendChild(row);
      });

      last.appendChild(wrap);
    }else{
      const body=document.createElement('div');
      body.className='rapid-final-body';
      body.textContent=payload;
      last.appendChild(body);
    }
  });
}


