function giApplyColonLeadNoTick(root){
  if(!root)return;
  root.querySelectorAll('li,p,span,div').forEach(el=>{
    let lead='';
    for(const child of el.childNodes){
      if(child.nodeType===1&&(child.tagName==='UL'||child.tagName==='OL'))break;
      lead+=' '+(child.textContent||'');
    }
    lead=lead.replace(/\s+/g,' ').trim();
    if(!lead.endsWith(':')||el.classList.contains('gi-colon-lead-no-tick'))return;
    let before='',computed=null;
    try{
      computed=window.getComputedStyle(el);
      before=(window.getComputedStyle(el,'::before').content||'').replace(/["']/g,'');
    }catch(_e){}
    if(!before.includes('âœ“'))return;

    // A colon-ending line is lead copy, not a checklist point. Keep its original
    // row height, remove only the generated tick and the divider immediately
    // above/below it. This makes it match the native plain-lead + checklist pattern.
    if(el.tagName==='LI'&&computed){
      el.style.setProperty('--gi-colon-original-pad-top',computed.paddingTop||'0px');
      el.style.setProperty('--gi-colon-original-pad-bottom',computed.paddingBottom||'0px');
      const hasNested=[...el.children].some(child=>child.tagName==='UL'||child.tagName==='OL');
      if(!hasNested)el.classList.add('gi-colon-lead-flat');
      const prev=el.previousElementSibling;
      if(prev&&prev.tagName==='LI')prev.classList.add('gi-before-colon-lead');
    }
    el.classList.add('gi-colon-lead-no-tick');
  });
}
