const GI_SEARCH_HISTORY_KEY='greenink.search-history.v1';
const GI_SEARCH_HISTORY_LIMIT=8;

function giLoadSearchHistory(){
  try{
    const raw=JSON.parse(localStorage.getItem(GI_SEARCH_HISTORY_KEY)||'[]');
    if(!Array.isArray(raw))return[];
    return raw
      .map(v=>String(v||'').trim())
      .filter(Boolean)
      .slice(0,GI_SEARCH_HISTORY_LIMIT);
  }catch(_){
    return[];
  }
}
function giSaveSearchHistory(items){
  try{
    localStorage.setItem(
      GI_SEARCH_HISTORY_KEY,
      JSON.stringify(items.slice(0,GI_SEARCH_HISTORY_LIMIT))
    );
  }catch(_){}
}
async function giRememberSearch(query){
  const q=String(query==null?"":query).trim();
  if(!q)return;
  if(state.authMode==="otp"){
    if(q.length<2)return;
    try{
      const res=await giAuthFetch(GIAPIBASE+"/me/search-history?q="+encodeURIComponent(q),{method:"POST",credentials:"include"});
      if(!res.ok)throw new Error("HTTP "+res.status);
    }catch(err){console.warn("Green Ink search history save failed:",err);}
    return;
  }
  const items=giLoadSearchHistory().filter(x=>x.toLocaleLowerCase()!==q.toLocaleLowerCase());
  items.unshift(q);
  giSaveSearchHistory(items);
}
async function giRemoveSearchHistory(query){
  const raw=String(query||'').trim();
  const q=raw.toLocaleLowerCase();

  if(state.authMode==="otp"){
    const item=giSearchHistoryApiCache.find(
      x=>String(x&&x.query||'').trim().toLocaleLowerCase()===q
    );
    if(!item||!item.id)return;

    try{
      const res=await giAuthFetch(
        GIAPIBASE+"/me/search-history/"+encodeURIComponent(item.id),
        {method:"DELETE",credentials:"include"}
      );
      if(!res.ok)throw new Error("HTTP "+res.status);

      giSearchHistoryApiCache=giSearchHistoryApiCache.filter(x=>x.id!==item.id);
      renderSearchIdle();
    }catch(err){
      console.warn("Green Ink search history remove failed:",err);
      giToast("Unable to remove search history");
    }
    return;
  }

  giSaveSearchHistory(
    giLoadSearchHistory().filter(x=>x.toLocaleLowerCase()!==q)
  );
  renderSearchIdle();
}

async function giClearSearchHistory(){
  if(state.authMode==="otp"){
    try{
      const res=await giAuthFetch(
        GIAPIBASE+"/me/search-history",
        {method:"DELETE",credentials:"include"}
      );
      if(!res.ok)throw new Error("HTTP "+res.status);

      giSearchHistoryApiCache=[];
      renderSearchIdle();
      return true;
    }catch(err){
      console.warn("Green Ink search history clear failed:",err);
      return false;
    }
  }

  try{localStorage.removeItem(GI_SEARCH_HISTORY_KEY)}catch(_){}
  renderSearchIdle();
  return true;
}
let giSearchHistoryApiCache=[];
async function giRefreshSearchHistory(){
  if(state.authMode!=="otp")return [];
  try{
    const res=await giAuthFetch(GIAPIBASE+"/me/search-history?limit="+GI_SEARCH_HISTORY_LIMIT,{credentials:"include"});
    if(!res.ok)throw new Error("HTTP "+res.status);
    const data=await res.json();
    giSearchHistoryApiCache=Array.isArray(data)?data:[];
    return giSearchHistoryApiCache;
  }catch(err){
    console.warn("Green Ink search history load failed:",err);
    return giSearchHistoryApiCache;
  }
}
async function renderSearchIdle(){
  const w=$('searchResultsWrap');
  const history=state.authMode==="otp"
    ? (await giRefreshSearchHistory()).map(x=>String(x&&x.query||"").trim()).filter(Boolean)
    : giLoadSearchHistory();
  if($('searchInput').value.trim())return;
  w._hits=[];

  if(!history.length){
    $('searchStatusLab').textContent='Start typing to search the TNPSC syllabus';
    w.innerHTML='';
    return;
  }

  $('searchStatusLab').textContent='Recent searches';

  const clock='<span class="search-history-clock" aria-hidden="true">'+
    '<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.5"></circle>'+
    '<path d="M12 7.2v5.2l3.2 2"></path></svg></span>';

  w.innerHTML=
    '<div class="search-history-wrap">'+
      history.map(q=>
        '<div class="search-history-row">'+
          '<button class="search-history-query" type="button" data-search-history-query="'+esc(q)+'">'+
            clock+
            '<span class="search-history-text">'+esc(q)+'</span>'+
          '</button>'+
          '<button class="search-history-remove" type="button" data-search-history-remove="'+esc(q)+'" aria-label="Remove '+esc(q)+' from search history">Ã—</button>'+
        '</div>'
      ).join('')+
    '</div>';
}
let giSearchRequestSeq=0;

async function runSearch(q){
  const raw=String(q||'').trim();
  const needle=raw.toLowerCase();
  const w=$('searchResultsWrap');
  const requestSeq=++giSearchRequestSeq;

  if(!needle){
    renderSearchIdle();
    return;
  }

  w._hits=[];

  const unitHits=[];
  UNITS.forEach((u,ui)=>{
    if(u.title.toLowerCase().includes(needle)){
      unitHits.push({ui,ci:null,title:u.title,unit:u.title});
    }
  });

  let chapterHits=[];

  if(needle.length<2){
    UNITS.forEach((u,ui)=>{
      u.chapters.forEach((c,ci)=>{
        if(c.title.toLowerCase().includes(needle)){
          chapterHits.push({ui,ci,title:c.title,unit:u.title});
        }
      });
    });
  }else{
    try{
      const res=await giAuthFetch(
        GIAPIBASE+"/search?q="+encodeURIComponent(raw)+"&limit=80",
        {credentials:"include"}
      );

      if(!res.ok)throw new Error("HTTP "+res.status);

      const data=await res.json();

      if(requestSeq!==giSearchRequestSeq)return;
      if(String($('searchInput').value||'').trim()!==raw)return;

      chapterHits=(Array.isArray(data.results)?data.results:[]).map(r=>{
        const chapterMatch=/^u(\d+)-c(\d+)$/i.exec(String(r&&r.chapterId||''));
        if(!chapterMatch)return null;

        const ui=Number(chapterMatch[1])-1;
        const ci=Number(chapterMatch[2])-1;

        if(!UNITS[ui]||!UNITS[ui].chapters[ci])return null;

        return {
          ui,
          ci,
          title:String(r.chapterTitle||UNITS[ui].chapters[ci].title),
          unit:String(r.unitTitle||UNITS[ui].title),
          accessible:r.accessible!==false
        };
      }).filter(Boolean);
    }catch(err){
      console.warn("Green Ink syllabus search API failed:",err);

      if(requestSeq!==giSearchRequestSeq)return;

      UNITS.forEach((u,ui)=>{
        u.chapters.forEach((c,ci)=>{
          if(c.title.toLowerCase().includes(needle)){
            chapterHits.push({ui,ci,title:c.title,unit:u.title});
          }
        });
      });
    }
  }

  if(requestSeq!==giSearchRequestSeq)return;

  const h=unitHits.concat(chapterHits);

  $('searchStatusLab').textContent=h.length+' result'+(h.length===1?'':'s');
  w._hits=h.slice(0,80);

  w.innerHTML=w._hits.map((x,i)=>{
    const locked=x.ci!=null&&(
      typeof x.accessible==='boolean'
        ? !x.accessible
        : !giCanAccessChapter(x.ui,x.ci)
    );

    const tail=locked
      ? giPremiumLockIcon('Premium chapter')
      : '<span class="topic-chevron">→</span>';

    return '<button class="search-row'+(locked?' is-premium-locked':'')+'" type="button" data-search-index="'+i+'" aria-label="'+esc(x.title+(locked?' â€” Premium chapter':''))+'">'+
      '<span class="search-copy"><span>'+
        '<span class="search-unit">UNIT '+(x.ui+1)+'</span>'+
        '<span class="search-title">'+esc(x.title)+'</span>'+
        '<span class="unit-subtitle">'+esc(x.unit)+'</span>'+
      '</span></span>'+tail+'</button>';
  }).join('')||'<div class="search-empty">No matching syllabus chapter.</div>';
}
function nav(n){if(n==='home')show('home');else if(n==='search')show('search');else if(n==='profile')show('profile');else if(n==='mode')show(state.hasOpenedChapter?'content':'home')}

let giOtpResendTimer=null;
let giOtpResendRemaining=0;

function giSetLoginError(inputId,errorId,message){
  const input=$(inputId),error=$(errorId);
  if(error){
    error.textContent=message||'';
    error.hidden=!message;
  }
  if(input)input.setAttribute('aria-invalid',message?'true':'false');
}
function giValidLoginIdentifier(value){
  const v=String(value||'').trim();
  const email=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const phone=v.replace(/[^\d]/g,'');
  return email.test(v)||(phone.length>=10&&phone.length<=15);
}
function giOtpInputs(){
  return [1,2,3,4].map(n=>$('loginOtp'+n)).filter(Boolean);
}
function giOtpValue(){
  return giOtpInputs().map(i=>i.value.replace(/\D/g,'').slice(0,1)).join('');
}
function giClearOtpBoxes(){
  giOtpInputs().forEach(i=>{
    i.value='';
    i.classList.remove('has-value');
  });
  const err=$('loginOtpError');
  if(err){err.textContent='';err.hidden=true}
}
function giPaintOtpBox(input){
  if(!input)return;
  input.value=input.value.replace(/\D/g,'').slice(0,1);
  input.classList.toggle('has-value',Boolean(input.value));
}
function giFocusOtp(index){
  const inputs=giOtpInputs();
  const target=inputs[Math.max(0,Math.min(inputs.length-1,index))];
  if(target)target.focus({preventScroll:true});
}
function giStartOtpResendTimer(seconds){
  clearInterval(giOtpResendTimer);
  giOtpResendRemaining=seconds;
  const btn=$('loginResendButton'),txt=$('loginResendText');

  const paint=()=>{
    if(!btn||!txt)return;
    if(giOtpResendRemaining>0){
      const mm=String(Math.floor(giOtpResendRemaining/60)).padStart(2,'0');
      const ss=String(giOtpResendRemaining%60).padStart(2,'0');
      btn.hidden=true;
      txt.textContent='Resend OTP in '+mm+':'+ss;
    }else{
      btn.hidden=false;
      txt.textContent="Didn't receive the code?";
      clearInterval(giOtpResendTimer);
      giOtpResendTimer=null;
    }
  };

  paint();
  giOtpResendTimer=setInterval(()=>{
    giOtpResendRemaining=Math.max(0,giOtpResendRemaining-1);
    paint();
  },1000);
}
function giResetOtpLogin(){
  clearInterval(giOtpResendTimer);
  giOtpResendTimer=null;
  giOtpResendRemaining=0;

  const identifierStep=$('loginIdentifierStep');
  const otpStep=$('loginOtpStep');
  if(identifierStep)identifierStep.hidden=false;
  if(otpStep)otpStep.hidden=true;

  if($('loginIdentifier')){
    $('loginIdentifier').value='';
    $('loginIdentifier').readOnly=false;
  }

  giClearOtpBoxes();
  giSetLoginError('loginIdentifier','loginIdentifierError','');

  const btn=$('loginResendButton'),txt=$('loginResendText');
  if(btn)btn.hidden=true;
  if(txt)txt.textContent='Resend OTP in 00:45';
}
async function giSendOtp(isResend){
  const input=$("loginIdentifier");
  const value=String(input?input.value:"").trim();
  giSetLoginError("loginIdentifier","loginIdentifierError","");

  if(!giValidLoginIdentifier(value)){
    giSetLoginError("loginIdentifier","loginIdentifierError","Enter a valid mobile number or Email ID.");
    if(input)input.focus();
    return;
  }

  try{
    const endpoint=isResend?"/auth/otp/resend":"/auth/otp/request";
    const res=await fetch(GIAPIBASE+endpoint,{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({identifier:value})});
    const data=await res.json();
    if(!res.ok)throw new Error(data&&data.message?data.message:"Unable to send OTP.");
    giAuthApiState.challengeId=data.challengeId?data.challengeId:"";
    giAuthApiState.identifier=value;
    $("loginOtpTarget").textContent=value;
    $("loginIdentifierStep").hidden=true;
    $("loginOtpStep").hidden=false;
    giClearOtpBoxes();
    giStartOtpResendTimer(Number(data.resendAfter)?Number(data.resendAfter):45);
    requestAnimationFrame(()=>giFocusOtp(0));
    if(data.debugOtp)console.log("Green Ink DEV OTP:",data.debugOtp);
  }catch(err){
    giSetLoginError("loginIdentifier","loginIdentifierError",err&&err.message?err.message:"Unable to send OTP.");
  }
}

async function giVerifyOtp(){
  const otp=giOtpValue();
  const err=$("loginOtpError");
  if(err){err.textContent="";err.hidden=true;}

  if(otp.length!==4){
    if(err){err.textContent="Enter the 4-digit OTP.";err.hidden=false;}
    const inputs=giOtpInputs();
    const firstEmpty=inputs.findIndex(i=>!i.value);
    giFocusOtp(firstEmpty<0?0:firstEmpty);
    return;
  }

  if(!giAuthApiState.challengeId){
    if(err){err.textContent="OTP session expired. Send OTP again.";err.hidden=false;}
    return;
  }

  try{
    const res=await fetch(GIAPIBASE+"/auth/otp/verify",{method:"POST",credentials:"include",headers:{"Content-Type":"application/json"},body:JSON.stringify({challengeId:giAuthApiState.challengeId,otp:otp})});
    const data=await res.json();
    if(!res.ok)throw new Error(data&&data.message?data.message:"Unable to verify OTP.");
    giAuthApiState.accessToken=data.accessToken?data.accessToken:"";
    giAuthApiState.expiresIn=Number(data.expiresIn)?Number(data.expiresIn):0;
    giAuthApiState.user=data.user?data.user:null;
    clearInterval(giOtpResendTimer);
    giOtpResendTimer=null;
    state.authMode="otp";
    const identity=data.user&&data.user.identifier?data.user.identifier:giAuthApiState.identifier;
    state.accountId=giNormalizeAccountId(String(identity||""));
    const meRes=await giAuthFetch(GIAPIBASE+"/me",{credentials:"include"});
    const me=await meRes.json();
    if(!meRes.ok)throw new Error(me&&me.message?me.message:"Unable to load account.");
    giAuthApiState.profile=me;
    Object.keys(giPyqAttemptCache).forEach(k=>delete giPyqAttemptCache[k]);
    Object.keys(pyqSessions).forEach(k=>delete pyqSessions[k]);
    giSearchHistoryApiCache=[];
    state.accessTier=me.premium?"premium":"free";giApplyTextSize();
    console.log("Green Ink account tier:",state.accessTier);
    show("home");
  }catch(ex){
    if(err){err.textContent=ex&&ex.message?ex.message:"Unable to verify OTP.";err.hidden=false;}
  }
}

function giHandleLoginAction(action){
  if(action==='guest'){state.authMode='guest';state.accountId='';state.accessTier='free';giApplyTextSize();show('home');return true}
  if(action==='send-otp'){giSendOtp(false);return true}
  if(action==='resend-otp'){giSendOtp(true);return true}
  if(action==='verify-otp'){giVerifyOtp();return true}
  if(action==='change-identifier'){
    clearInterval(giOtpResendTimer);
    giOtpResendTimer=null;
    $('loginOtpStep').hidden=true;
    $('loginIdentifierStep').hidden=false;
    giClearOtpBoxes();
    requestAnimationFrame(()=>$('loginIdentifier')?.focus({preventScroll:true}));
    return true;
  }
  return false;
}

