$('loginIdentifier').addEventListener('keydown',e=>{
  if(e.key==='Enter'){e.preventDefault();giSendOtp(false)}
});
$('loginIdentifier').addEventListener('input',()=>{
  if($('loginIdentifier').getAttribute('aria-invalid')==='true'){
    giSetLoginError('loginIdentifier','loginIdentifierError','');
  }
});
giOtpInputs().forEach((input,index,inputs)=>{
  input.addEventListener('input',e=>{
    const raw=e.target.value;
    if(raw.length>1){
      const digits=raw.replace(/\D/g,'').slice(0,4);
      digits.split('').forEach((d,offset)=>{
        const target=inputs[index+offset];
        if(target){target.value=d;giPaintOtpBox(target)}
      });
      giFocusOtp(Math.min(inputs.length-1,index+digits.length));
      return;
    }
    giPaintOtpBox(e.target);
    const err=$('loginOtpError');
    if(err){err.textContent='';err.hidden=true}
    if(e.target.value&&index<inputs.length-1)giFocusOtp(index+1);
  });

  input.addEventListener('keydown',e=>{
    if(e.key==='Backspace'&&!e.target.value&&index>0){
      e.preventDefault();
      inputs[index-1].value='';
      giPaintOtpBox(inputs[index-1]);
      giFocusOtp(index-1);
      return;
    }
    if(e.key==='ArrowLeft'&&index>0){e.preventDefault();giFocusOtp(index-1);return}
    if(e.key==='ArrowRight'&&index<inputs.length-1){e.preventDefault();giFocusOtp(index+1);return}
    if(e.key==='Enter'){e.preventDefault();giVerifyOtp()}
  });

  input.addEventListener('paste',e=>{
    const digits=(e.clipboardData?.getData('text')||'').replace(/\D/g,'').slice(0,4);
    if(!digits)return;
    e.preventDefault();
    digits.split('').forEach((d,offset)=>{
      const target=inputs[offset];
      if(target){target.value=d;giPaintOtpBox(target)}
    });
    giFocusOtp(Math.min(inputs.length-1,digits.length));
  });
});
