$('paymentAuthIdentifier')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();giSendPaymentAuthOtp()}});
(()=>{
  const inputs=giPaymentAuthOtpInputs();
  inputs.forEach((input,index)=>{
    input.addEventListener('input',()=>{
      input.value=String(input.value||'').replace(/\D/g,'').slice(-1);
      if(input.value&&index<inputs.length-1)inputs[index+1].focus({preventScroll:true});
    });
    input.addEventListener('keydown',e=>{
      if(e.key==='Backspace'&&!input.value&&index>0){e.preventDefault();inputs[index-1].value='';inputs[index-1].focus({preventScroll:true})}
      if(e.key==='Enter'){e.preventDefault();giVerifyPaymentAuthOtp()}
    });
    input.addEventListener('paste',e=>{
      const digits=(e.clipboardData?.getData('text')||'').replace(/\D/g,'').slice(0,4);
      if(!digits)return;
      e.preventDefault();inputs.forEach((el,i)=>el.value=digits[i]||'');inputs[Math.min(digits.length,4)-1]?.focus({preventScroll:true});
    });
  });
})();
